CREATE TABLE IF NOT EXISTS astra_event_archive(receipt_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,bot_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,bot_json LONGTEXT NOT NULL,transport VARCHAR(32) NOT NULL,event_type VARCHAR(128) NOT NULL,opcode INTEGER NOT NULL,sequence_number BIGINT,platform_event_id LONGTEXT NOT NULL,received_at BIGINT NOT NULL,raw_packet LONGTEXT NOT NULL,event_json LONGTEXT NOT NULL,INDEX astra_archive_bot(bot_key,received_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;